INSERT INTO `v1_4c06921a24521962f469d06257a46a22a48fb0d5b1de9a32fccae813b8e65b93` VALUES (1, 1, 0, "直感、あったんですよね。\nアオイさんほど詳しくはないですが、\nわたしも草花が好きなので。\nこの人とは仲良くなれそう、みたいな。", 0, 11, 0, 72017, 10, 72, 1);
