INSERT INTO `v1_4c06921a24521962f469d06257a46a22a48fb0d5b1de9a32fccae813b8e65b93` VALUES (1, 1, 0, "そしたらアオイさん、\n顔を真っ赤にして、ブンブン！　って、\n首を縦に振ってくれて。\nやった！　って思ったんですよね。", 0, 11, 0, 72025, 10, 72, 1);
