INSERT INTO `v1_4c06921a24521962f469d06257a46a22a48fb0d5b1de9a32fccae813b8e65b93` VALUES (1, 1, 0, "と、不退転の決意を申し上げたら、\nミサト様、「は～い♪」と、\n二つ返事で分かってくださって。", 0, 11, 0, 82025, 10, 82, 1);
